    53	// Format date for display in Swedish (e.g., "Lör 21 mars")
    54	function formatDate(dateString) {
    55	  if (!dateString) return '';
    56	  const date = new Date(dateString);
    57	  const daysSwedish = ['Sön', 'Mån', 'Tis', 'Ons', 'Tors', 'Fre', 'Lör'];
    58	  const monthsSwedish = ['jan', 'feb', 'mars', 'apr', 'maj', 'jun', 'jul', 'aug', 'sep', 'okt', 'nov', 'dec'];
    59	  return `${daysSwedish[date.getDay()]} ${date.getDate()} ${monthsSwedish[date.getMonth()]}`;
    60	}
