    62	// Format full date for details (e.g., "Friday, March 20, 2026")
    63	function formatFullDate(dateString) {
    64	  if (!dateString) return '';
    65	  const date = new Date(dateString);
    66	  const days = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
    67	  const months = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];
    68	  return `${days[date.getDay()]}, ${months[date.getMonth()]} ${date.getDate()}, ${date.getFullYear()}`;
